module fsm (
    input clk,
    input reset,
    input x,
    output reg y);

    parameter M=0, N=1, O=2, P=3, Q=4;
    reg [2:0] state, next;

    always @(posedge clk) begin
        if (reset) state <= M;
        else state <= next;
    end

    always_comb begin
        case (state)
            M: next = x ? N : M;
            N: next = x ? N : O;
            O: next = x ? N : P;
            P: next = x ? N : Q;
            Q: next = x ? N : M;
            default: next = 'x;
        endcase
    end

    assign y = (state == Q);

endmodule

