code:
module up_down_counter(
    input clk,           // Clock signal.
    input rst_n,         // Active-low reset signal.
    input enable,        // Enable signal.
    input up_down,       // Control signal for count direction. 1 for up count, 0 for down count.

    output [2:0] count,  // 3-bit counter output.
    output max_min_reached // Output flag. 1 indicates counter has reached maximum or minimum value.
);

reg [2:0] count_r; // 3-bit counter register.
reg max_min_reached_r; // Flag register.

//------------------------------------------------
// Perform counting operations
always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        count_r <= 3'b000;
    else if (enable) begin
        if (up_down)
            count_r <= count_r + 1'b1;
        else
            count_r <= count_r - 1'b1;
    end
end

//------------------------------------------------
// Check for maximum or minimum count value
always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        max_min_reached_r <= 1'b0;
    else if (count_r == 3'b111 || count_r == 3'b000)
        max_min_reached_r <= 1'b1;
    else
        max_min_reached_r <= 1'b0;
end

assign count = count_r;
assign max_min_reached = max_min_reached_r;

endmodule

