description:
Design a module that performs the modulo operation for a 16-bit unsigned dividend and a 4-bit unsigned divisor. The module calculates the remainder of the division, outputting a 4-bit result. If the divisor is zero, it outputs zero to avoid division by zero errors. The design accounts for potential negative dividends by converting them to positive before computing the remainder, ensuring that the output is always non-negative.
module top_module(
  input [15:0] dividend,
  input [3:0] divisor,
  output [3:0] remainder
);

code:
module top_module(
  input [15:0] dividend,
  input [3:0] divisor,
  output [3:0] remainder
);reg [15:0] dividend_reg;
  reg [3:0] divisor_reg;
  reg [3:0] remainder_reg;

  always @(*) begin
    dividend_reg = dividend;
    divisor_reg = divisor;

    if (divisor_reg == 0) begin
      remainder_reg = 0;
    end else begin
      if (dividend_reg < 0) begin
        remainder_reg = -((-dividend_reg) % divisor_reg);
      end else begin
        remainder_reg = dividend_reg % divisor_reg;
      end
    end
  end

  assign remainder = remainder_reg;

endmodule

