module sequence_detector (
    input clk,
    input in,
    input reset,
    output detected);parameter S0=0, S1=1, S01=2, S010=3;
    reg [1:0] state;
    reg [1:0] next;

    always_comb begin
        case (state)
            S0: next = in ? S0 : S1;
            S1: next = in ? S01 : S0;
            S01: next = in ? S0 : S010;
            S010: next = in ? S0 : S1;
        endcase
    end

    always @(posedge clk) begin
        if (reset) state <= S0;
        else state <= next;
    end

    assign detected = (state == S010);

endmodule

