description:
Design a clock generator that produces a derived external clock signal, `ext_clk`, from an input clock `clk_in`. Upon reset, the module resets the counter and sets the external clock to low. On each rising edge of `clk_in`, the counter increments until it reaches a value of 4, at which point the counter resets to zero and toggles the output `ext_clk`. This effectively creates a clock signal that has a frequency one-fourth that of the input clock.
module top_module(
    input clk_in,
    input rst,
    output reg ext_clk
);

code:
module top_module(
    input clk_in,
    input rst,
    output reg ext_clk
);reg [3:0] counter;

always @(posedge clk_in, posedge rst) begin
    if (rst) begin
        counter <= 0;
        ext_clk <= 0;
    end else begin
        counter <= counter + 1;
        if (counter == 4) begin
            counter <= 0;
            ext_clk <= ~ext_clk;
        end
    end
end

endmodule

