module fsm (
  input clk,
  input reset,
  input c,
  output reg u);parameter S0=0, S1=1, S2=2, S3=3;
	reg [1:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= S3;
		else state <= next;
	end

	always_comb begin
		case (state)
			S0: next = c ? S2 : S1;
			S1: next = c ? S0 : S3;
			S2: next = c ? S3 : S0;
			S3: next = c ? S1 : S2;
			default: next = 'x;
		endcase
	end

	assign u = (state == S0) || (state == S2);

endmodule

