module top_module(
    CLK,
    RESET,
    ENABLE,
    TRIG_OUT,
    COUNT
    );parameter WIDTH = 10;
    parameter MAX = 800;
    input CLK;
    input RESET;
    input ENABLE;
    output  TRIG_OUT;
    output  [WIDTH-1:0] COUNT;    
    reg [WIDTH-1:0] count_value = 0;
    reg trig;

    always@(posedge CLK) begin
        if (RESET)
            count_value <= 0;
        else begin
            if (ENABLE)begin           
                if(count_value == MAX)
                    count_value <= 0;
                else
                    count_value <= count_value + 1;
            end
        end
    end 

    always@(posedge CLK)begin
        if (RESET)
            trig <= 0;
        else begin
            if (count_value == MAX && ENABLE)
                trig <= 1;
            else 
                trig <= 0;
        end
