`timescale 1ns/1ps

module top_module_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg ldcand;
    reg ldencounter;
    reg ldlier;
    reg ldp;
    reg ldrstcounter;
    reg ldshift;
    reg ldsum;
    reg [31:0] multiplicand;
    reg [31:0] multiplier;
    wire [5:0] counter;
    wire [63:0] product;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .clk(clk),
        .ldcand(ldcand),
        .ldencounter(ldencounter),
        .ldlier(ldlier),
        .ldp(ldp),
        .ldrstcounter(ldrstcounter),
        .ldshift(ldshift),
        .ldsum(ldsum),
        .multiplicand(multiplicand),
        .multiplier(multiplier),
        .counter(counter),
        .product(product)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            ldcand = 0;
            ldencounter = 0;
            ldlier = 0;
            ldp = 0;
            ldrstcounter = 1;
            ldshift = 0;
            ldsum = 0;
            multiplicand = 0;
            multiplier = 0;
            @(posedge clk);
            #1 ldrstcounter = 0;
        end
        endtask
    task perform_multiplication;

        input [31:0] a;
        input [31:0] b;
        integer i;
        begin

            multiplicand = a;
            multiplier = b;
            ldrstcounter = 1;
            ldcand = 1;
            ldlier = 1;
            ldp = 1;
            ldencounter = 0;
            ldshift = 0;
            ldsum = 0;
            @(posedge clk);
            #1;


            ldrstcounter = 0;
            ldcand = 0;
            ldlier = 0;
            ldp = 0;


            for (i = 0; i < 32; i = i + 1) begin

                if (product[0] == 1'b1) begin
                    ldsum = 1;
                    @(posedge clk);
                    #1;
                    ldsum = 0;
                end


                ldshift = 1;
                ldencounter = 1;
                @(posedge clk);
                #1;
                ldshift = 0;
