description:
Design a 2-bit wide, 4-to-1 multiplexer with additional functionalities for negating inputs. The module selects between four different options based on the input select lines `sa` and `sb`: when both are low (00), it outputs `a`; when `sa` is low and `sb` is high (01), it outputs `b`; when `sa` is high and `sb` is low (10), it outputs the bitwise NOT of `a`; and when both are high (11), it outputs the bitwise NOT of `b`. This design allows for straightforward data selection while incorporating the ability to invert selected inputs.
module top_module(
   // Outputs
   muxed,
   // Inputs
   sa, sb, a, b
   );

code:
module top_module(
   // Outputs
   muxed,
   // Inputs
   sa, sb, a, b
   );input sa, sb;
   input [71:0] a, b;
   output [71:0] muxed;

   wire [71:0] not_a = ~a;
   wire [71:0] not_b = ~b;

   assign muxed = (sa == 0 && sb == 0) ? a :
                  (sa == 0 && sb == 1) ? b :
                  (sa == 1 && sb == 0) ? not_a :
                  (sa == 1 && sb == 1) ? not_b : 0;
endmodule

