module top_module(
    input clk,
    input rst,
    input [7:0] red,
    input [7:0] green,
    input [7:0] blue,
    output reg hsync,
    output reg vsync,
    output reg blank,
    output reg [23:0] vga
);parameter H_FRONT_PORCH = 16;
    parameter H_SYNC_WIDTH = 96;
    parameter H_BACK_PORCH = 48;
    parameter V_FRONT_PORCH = 10;
    parameter V_SYNC_WIDTH = 2;
    parameter V_BACK_PORCH = 33;
    parameter H_RES = 640;
    parameter V_RES = 480;
    parameter PIXEL_CLOCK = 25E6;
    parameter FRAME_RATE = 60;

    reg [10:0] h_count;
    reg [9:0] v_count;

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            h_count <= 0;
            v_count <= 0;
            hsync <= 1;
            vsync <= 1;
            blank <= 1;
        end else begin
            if (h_count >= H_RES + H_FRONT_PORCH + H_SYNC_WIDTH + H_BACK_PORCH - 1) begin
                h_count <= 0;
                if (v_count >= V_RES + V_FRONT_PORCH + V_SYNC_WIDTH + V_BACK_PORCH - 1) begin
                    v_count <= 0;
                end else begin
                    v_count <= v_count + 1;
                end
            end else begin
                h_count <= h_count + 1;
            end
            if (h_count >= H_RES + H_FRONT_PORCH && h_count < H_RES + H_FRONT_PORCH + H_SYNC_WIDTH) begin
                hsync <= 0;
            end else begin
                hsync <= 1;
            end
            if (v_count >= V_RES + V_FRONT_PORCH && v_count < V_RES + V_FRONT_PORCH + V_SYNC_WIDTH) begin
                vsync <= 0;
            end else begin
                vsync <= 1;
            end
            if (h_count >= H_RES + H_FRONT_PORCH && v_count >= V_RES + V_FRONT_PORCH) begin
                blank <= 0;
                vga <= {red, green, blue};
            end else begin
                blank <= 1;
                vga <= 0;
            end
        end
    end

endmodule

