module top_module (
        input clk,
        input reset,
        input x,
        output reg out);parameter S0=0, S1=1, S2=2, S3=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= S0;
		else state <= next;


	always_comb begin
		case (state)
			S0: next = x ? S1 : S0;
			S1: next = x ? S2 : S3;
			S2: next = x ? S2 : S3;
			S3: next = x ? S1 : S0;
			default: next = 'x;
		endcase
	end

	assign out = (state == S2) || (state == S3);

endmodule

