module up_down_counter (CLK, RST, UP, COUNT);
input CLK, RST, UP;
output reg [2:0] COUNT;

always @(posedge CLK or posedge RST) begin
	if (RST) begin
		COUNT <= 3'b000;
	end
	else if (UP) begin
		COUNT <= COUNT + 1;
	end
	else begin
		COUNT <= COUNT - 1;
	end
end

