    if (rst) begin
      wr_ptr <= 3'b0;
      rd_ptr <= 3'b0;
      count <= 3'b0;
      full <= 1'b0;
      empty <= 1'b1;
    end else if (wr_en && !full) begin
      buffer[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      count <= count + 1;
      if (count == 8) full <= 1'b1;
      empty <= 1'b0;
    end
  end

  always @(posedge rd_clk or negedge rst) begin
    if (rst) begin
      wr_ptr <= 3'b0;
      rd_ptr <= 3'b0;
      count <= 3'b0;
      full <= 1'b0;
      empty <= 1'b1;
    end else if (rd_en && !empty) begin
      dout <= buffer[rd_ptr];
      rd_ptr <= rd_ptr + 1;
      count <= count - 1;
      if (count == 1) empty <= 1'b1;
      full <= 1'b0;
    end
  end

