module top_module(
  input [15:0] a,
  input [15:0] b,
  output reg [31:0] result
);reg [31:0] res;
  reg [15:0] b_temp; // Temporary variable for manipulation
  reg [3:0] i;

  always @(*) begin
    res = 0;
    b_temp = b; // Assign b to temporary variable
    for (i = 0; i < 16; i = i + 1) begin
      if (b_temp[0] == 1) begin
        res = res + (a << i);
      end
      b_temp = b_temp >> 1; // Shift the temporary variable
    end
    result = res;
  end

endmodule

module top_module(
