  i1,
  i2,
  i3
);output q;
  input i0;
  input i1;
  input i2;
  input i3;
  wire [1:0] int_0n;

  // AND gate for int_0n[0]
  assign int_0n[0] = i0 & i1;

  // AND gate for int_0n[1]
  assign int_0n[1] = i2 & i3;

  // OR gate for q
  assign q = int_0n[0] | int_0n[1];
endmodule

