module top_module(
  input signed [n-1:0] input_num,
  input signed [n-1:0] sat_max,
  input signed [n-1:0] sat_min,
  output signed [n-1:0] output_num
);parameter n = 8; // total number of bits
parameter i = 4; // number of integer bits
parameter f = 4; // number of fractional bits

// Calculate the rounding factor
parameter rounding_factor = (1 << (f-1));

// Round the input_num to the nearest integer
wire [n-1:0] rounded_num = input_num + rounding_factor;
assign rounded_num = rounded_num >> f;

// Check if the rounded number is greater than the saturation maximum value
wire [n-1:0] max_num = sat_max << f;
wire [n-1:0] is_greater_than_max = (rounded_num > max_num);

// Check if the rounded number is less than the saturation minimum value
wire [n-1:0] min_num = sat_min << f;
wire [n-1:0] is_less_than_min = (rounded_num < min_num);

// Set the output_num to the saturation maximum value if the rounded number is greater than the saturation maximum value
assign output_num = (is_greater_than_max) ? sat_max : rounded_num;

// Set the output_num to the saturation minimum value if the rounded number is less than the saturation minimum value
assign output_num = (is_less_than_min) ? sat_min : output_num;

endmodule

