	always@(posedge clk or negedge nRst) begin
		if(!nRst) begin
	      drive          <= 32'd0;	
         int_error_old  <= 32'd0;
		end else begin 
         drive <= (Kp*error) + (Ki*int_error_new);
         int_error_old <= int_error_new;
		end
	end
endmodule

description:
Design a sequence detector that recognizes a specific alternating binary sequence consisting of '10' and '01'. The module transitions through three states (START, STATE1, and ACCEPT) based on the input signal, tracking the expected sequence for proper detection. When the designated sequence is identified, the output signal is asserted HIGH; otherwise, it remains LOW. The state machine resets to the START state after detecting the sequence or upon receiving an incorrect input.
module top_module(
  input in,
  output out
);

code:
module top_module(
  input in,
  output out
);// Define the states of the state machine
  parameter START = 2'b00;
  parameter STATE1 = 2'b01;
  parameter ACCEPT = 2'b10;

  // Define the sequence to be detected
  parameter SEQ1 = 2'b10;
  parameter SEQ2 = 2'b01;
  parameter SEQ3 = 2'b10;
  parameter SEQ4 = 2'b01;

  // Define the current state and next state variables
  reg [1:0] current_state, next_state;

  // Define the expected sequence variable
  reg [1:0] expected_seq;

  // Define the combinational logic to compare the current input with the expected sequence
  assign out = (current_state == ACCEPT) ? 1 : 0;

  // Define the state machine transitions
  always @ (posedge in) begin
    case (current_state)
      START: begin
        next_state = STATE1;
        expected_seq = SEQ1;
      end
      STATE1: begin
        if (in == expected_seq[1]) begin
          next_state = (expected_seq == SEQ4) ? ACCEPT : STATE1;
          expected_seq = (expected_seq == SEQ1) ? SEQ2 : (expected_seq == SEQ2) ? SEQ3 : SEQ4;
        end
        else begin
          next_state = START;
          expected_seq = SEQ1;
        end
      end
      ACCEPT: begin
        next_state = START;
        expected_seq = SEQ1;
      end
    endcase
    current_state <= next_state;
  end

endmodule

module d_ff (
    input wire clk,
    input wire reset,
    input wire D,
    output reg Q
    );

always @(posedge clk or posedge reset) begin
    if (reset)
        Q <= 1'b0;
    else
        Q <= D;
end

endmodule

